import{_ as t,o,c as r,ah as i}from"./chunks/framework.DDXs_i7t.js";const p=JSON.parse('{"title":"Production Start: The Voices Come Alive","description":"We begin with the dubbing of the Horten Mystery. First tests with AI-generated character voices are underway.","frontmatter":{"title":"Production Start: The Voices Come Alive","description":"We begin with the dubbing of the Horten Mystery. First tests with AI-generated character voices are underway.","date":"2026-02-27T00:00:00.000Z"},"headers":[],"relativePath":"en/logbuch/2026-02-27-produktionsstart-audio.md","filePath":"en/logbuch/2026-02-27-produktionsstart-audio.md"}'),a={name:"en/logbuch/2026-02-27-produktionsstart-audio.md"};function s(n,e,l,h,c,d){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="🎙️-production-start-the-voices-come-alive" tabindex="-1">🎙️ Production Start: The Voices Come Alive <a class="header-anchor" href="#🎙️-production-start-the-voices-come-alive" aria-label="Permalink to &quot;🎙️ Production Start: The Voices Come Alive&quot;">​</a></h1><p>A big moment for the project: we have left the purely text-based phase. Today, the first <strong>AI audio prototypes</strong> for the roles of Heidi Horten and Helmut Horten were generated.</p><p><strong>Our findings from the first run:</strong></p><ul><li><strong>Heidi (Minichmayr-style):</strong> The mix of elegance and cool arrogance can be captured surprisingly well via ElevenLabs. Especially the pauses (&quot;...You know...&quot;) give the character an eerie depth.</li><li><strong>The Pointillism Effect:</strong> When you layer the voice over the atmosphere sounds (Wörthersee splashing), the boundaries between AI and reality finally blur.</li></ul><p>We invite all supporters to follow the progress in the <a href="/en/hoerbuch/audio-showcase.html">Audio Showcase</a>. There we will soon integrate the first audio samples directly.</p><p><em>Documented by Volti Sodala &amp; Gemini CLI. February 2026.</em></p>',6)])])}const m=t(a,[["render",s]]);export{p as __pageData,m as default};
